/// The `asm_sub_register` lint detects using only a subset of a register
/// for inline asm inputs.
///
/// ### Example
///
/// ```rust,ignore (fails on non-x86_64)
/// #[cfg(target_arch="x86_64")]
/// use std::arch::asm;
///
/// fn main() {
///     #[cfg(target_arch="x86_64")]
///     unsafe {
///         asm!("mov {0}, {0}", in(reg) 0i16);
///     }
/// }
/// ```
///
/// This will produce:
