///     }
/// }
///
/// struct Point { x: FancyInteger, y: FancyInteger }
///
/// fn main() {
///   let p = Point { x: FancyInteger(10), y: FancyInteger(20) };
///
///   let c = || {
///      let x = p.x;
///   };
///
///   c();
///
///   // ... More code ...
/// }
/// ```
