// rustc-lint: compiler/rustc_lint_defs/src/builtin.rs:4259 NEVER_TYPE_FALLBACK_FLOWING_INTO_UNSAFE
/// The `never_type_fallback_flowing_into_unsafe` lint detects cases where never type fallback
/// affects unsafe function calls.
///
/// ### Never type fallback
///
/// When the compiler sees a value of type [`!`] it implicitly inserts a coercion (if possible),
/// to allow type check to infer any type:
///
/// ```ignore (illustrative-and-has-placeholders)
/// // this
/// let x: u8 = panic!();
///
/// // is (essentially) turned by the compiler into
/// let x: u8 = absurd(panic!());
///
/// // where absurd is a function with the following signature
/// // (it's sound, because `!` always marks unreachable code):
/// fn absurd<T>(never: !) -> T { ... }
/// ```
///
/// While it's convenient to be able to use non-diverging code in one of the branches (like
/// `if a { b } else { return }`) this could lead to compilation errors:
///
/// ```compile_fail
/// // this
/// { panic!() };
///
/// // gets turned into this
/// { absurd(panic!()) }; // error: can't infer the type of `absurd`
/// ```
///
/// To prevent such errors, compiler remembers where it inserted `absurd` calls, and if it
/// can't infer their type, it sets the type to fallback. `{ absurd::<Fallback>(panic!()) };`.
/// This is what is known as "never type fallback".
///
/// ### Example
///
/// ```rust,compile_fail
/// fn main() {
///     if true {
///         // return has type `!` which, is some cases, causes never type fallback
///         return
///     } else {
///         // `zeroed` is an unsafe function, which returns an unbounded type
///         unsafe { std::mem::zeroed() }
///     };
///     // depending on the fallback, `zeroed` may create `()` (which is completely sound),
///     // or `!` (which is instant undefined behavior)
/// }
/// ```
///
/// {{produces}}
///
/// ### Explanation
///
/// The never type fallback used to be `()`, meaning that `!` got spontaneously coerced to `()`.
/// Since then the never type fallback has been changed to `!`, making the above code undefined
/// behavior. Instead of depending on the fallback, you should specify the type explicitly:
/// ```
/// if true {
///     return
/// } else {
///     // type is explicitly specified, fallback can't hurt us no more
///     unsafe { std::mem::zeroed::<()>() }
/// };
/// ```
///
/// See [Tracking Issue for making `!` fall back to `!`](https://github.com/rust-lang/rust/issues/123748).
///
/// [`!`]: https://doc.rust-lang.org/core/primitive.never.html
/// [`()`]: https://doc.rust-lang.org/core/primitive.unit.html
export const NEVER_TYPE_FALLBACK_FLOWING_INTO_UNSAFE: Lint = Object.freeze<Lint>({
  name: "NEVER_TYPE_FALLBACK_FLOWING_INTO_UNSAFE",
  default_level: "Deny",
  desc: "never type fallback affecting unsafe function calls",
  edition_lint_opts: undefined,
  report_in_external_macro: true,
  future_incompatible: undefined,
  is_externally_loaded: false,
  feature_gate: undefined,
  crate_level_only: false,
  eval_always: false,
  ignore_deny_warnings: false,
  rust_version: undefined,
});

